def count(values):
    total=0
    item=None
    for item in values:
        if item==2: continue
        if item==5: break
        total+=item
    else: total+=100
    return item,total
print([count(values) for values in [[],[1],[1,2,3],[1,2,3,4,5,6],(1,2,3),range(3),b'123']])
def missing(values):
    for item in values: pass
    return item
try: missing([])
except UnboundLocalError: print('unbound')

def compute(values):
    total=0
    for i in values:
        for j in (1,2,3):
            if j==2: continue
            total+=i*10+j
            if i==2: break
        else: total+=100
    return total
print(compute([0,1,2,3]))
def words(value):
    first=None
    for word in value.upper().split():
        if first is None: first=word
        if word=='STOP': break
    return first,word
print(words('ßé café stop later'))
def select(values):
    for item in values:
        if item>2: return item
    return None
print(select((1,2,3,4)),select(()))

def take(values):
    total=0
    for item in values:
        if item==1: values.append(4)
        total+=item
    return item,total
values=[1,2,3]
print(take(values),values)
def change(values):
    for item in values:
        values['new']=9
    return item
try: change({'a':1,'b':2})
except RuntimeError: print('changed')
def keep(values):
    first=None
    for item in values:
        if first is None: first=item
    return first,item
values=[[1],[2]]
first,last=keep(values)
first.append(9)
print(first,last,first is values[0],last is values[1])

events=[]
class Values:
    def __iter__(self):
        events.append('iter')
        return iter((1,2,3))
def total(values):
    result=0
    for item in values: result+=item
    return result
print(total(Values()),events)
class Number:
    def __radd__(self,other):
        events.append(other)
        return other+7
print(total([1,2,Number(),4]),events)
